    [2905]={name="Goat Fur Cloak",quality=1,ilvl=10,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'The Perfect Stout'. Pick it over the other reward choices. Starts with Rejold Barleybrew in Dun Morogh. Objective: Bring 6 Shimmerweeds to Rejold Barleybrew in the Brewnall Village.",zone="Dun Morogh",questName="The Perfect Stout",lore="I'm on a quest, a quest to make the perfect stout. I know I can do it -- brewing's in my blood. I just need to find the right recipe... The Frostmane trolls grow a plant, shimmerweed, high up in the hills to the east."},
