    [10547]={name="Camping Knife",quality=1,ilvl=8,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'Return to Bellowfiz'. Pick it over the other reward choices. Starts with Rejold Barleybrew in Dun Morogh. Objective: Give the cask of Evershine to Pilot Bellowfiz at Steelgrill's Depot.",zone="Dun Morogh",questName="Return to Bellowfiz",lore="Here's your cask of Evershine. And again, thank you for the hunting earlier."},
